package config

import "sort"

// TitlesConfig configures short row titles: a 2-5 word title generated by a
// Nous backend from a row's long recap (internal/shorttitle). Global config
// only: it makes paid network calls.
type TitlesConfig struct {
	// Enabled switches the feature. nil (unset) means enabled whenever a
	// nous-kind backend is configured.
	Enabled *bool `json:"enabled,omitempty"`
	// Backend names a nous-kind entry in Backends. Empty means the first
	// nous-kind backend by name.
	Backend string `json:"backend,omitempty"`
	// Model is the model id sent to the backend. Empty means the backend's
	// models.haiku, else its model.
	Model string `json:"model,omitempty"`
	// HourlyCap is the machine-wide cap on title requests per rolling hour.
	// Zero or negative means DefaultTitlesHourlyCap.
	HourlyCap int `json:"hourly_cap,omitempty"`
}

// DefaultTitlesHourlyCap is the title request cap per hour when
// titles.hourly_cap is unset.
const DefaultTitlesHourlyCap = 120

// EffectiveHourlyCap is HourlyCap, with values <= 0 meaning the default.
func (t TitlesConfig) EffectiveHourlyCap() int {
	if t.HourlyCap <= 0 {
		return DefaultTitlesHourlyCap
	}
	return t.HourlyCap
}

// TitleSettings is the effective titles configuration (see EffectiveTitles).
type TitleSettings struct {
	Enabled     bool
	BackendName string
	Backend     BackendConfig
	Model       string
}

// EffectiveTitles resolves the titles block against the backends. It is
// disabled when titles.enabled is false, when no nous-kind backend exists,
// when titles.backend names a missing or non-nous backend, or when the
// resulting model id is not a valid model slug.
func (c Config) EffectiveTitles() TitleSettings {
	t := c.Titles
	if t.Enabled != nil && !*t.Enabled {
		return TitleSettings{}
	}
	name := t.Backend
	if name == "" {
		name = firstNousBackend(c.Backends)
	}
	b, ok := c.Backends[name]
	if name == "" || !ok || !b.IsNous() {
		return TitleSettings{}
	}
	model := t.Model
	if model == "" {
		model = b.AliasModel("haiku")
	}
	if model == "" || !safeModelValue.MatchString(model) {
		return TitleSettings{}
	}
	return TitleSettings{Enabled: true, BackendName: name, Backend: b, Model: model}
}

// firstNousBackend is the alphabetically first nous-kind backend name, or "".
func firstNousBackend(backends map[string]BackendConfig) string {
	names := make([]string, 0, len(backends))
	for n, b := range backends {
		if b.IsNous() {
			names = append(names, n)
		}
	}
	if len(names) == 0 {
		return ""
	}
	sort.Strings(names)
	return names[0]
}
